class Solution {public:
 int minXor(vector<int>& nums,int k){
  int n=nums.size();vector<int> px(n+1);for(int i=0;i<n;++i)px[i+1]=px[i]^nums[i];
  const int INF=INT_MAX;vector<vector<int>> dp(k+1,vector<int>(n+1,INF));dp[0][0]=0;
  for(int t=1;t<=k;++t)for(int i=t;i<=n;++i)for(int j=t-1;j<i;++j)if(dp[t-1][j]!=INF)
   dp[t][i]=min(dp[t][i],max(dp[t-1][j],px[i]^px[j]));
  return dp[k][n];
 }
};
